-- ── story 5-2b: receipt and dispatch emails ───────────────────────────────
-- Generated by drizzle-kit (the five columns and the seven indexes — made
-- IF NOT EXISTS by hand, the 6-2a lint) and hand-amended: the size guard
-- above the index builds, the CHECKs (the email-events subset, the Reply-To
-- shape, the widened template vocabulary, the client-mail shape, the dedupe
-- key bound, the priority), and the post-migration probe (drizzle-kit is
-- blind to all of them; `bun run db:generate` afterwards reports "No schema
-- changes").
--
-- Additive: no data statement — every existing contact reads no email events
-- (nobody is emailed until staff opt them in), every client no Reply-To, every
-- existing mail row is account mail (client_id and dedupe_key null, priority
-- 0 — the constant default makes the column a metadata-only add). No foreign
-- keys (IMPLEMENTATION-GUIDE §3). RLS is unchanged: the 0089 tenant policy
-- covers the new columns (no portal route reads email_messages; a future
-- portal read adds its client clause with its own probe).
--
-- The indexes on email_messages are PLAIN builds: at deploy the table holds
-- only account mail (invites, resets — final rows purged at 90 days), so
-- DEPLOY §5 does not apply. The guard below refuses the migration when the
-- table holds more than 200,000 rows and they are not already built under
-- these names (pre-build them CONCURRENTLY, DEPLOY §5, then re-run). Three of
-- them close PENDING (mail): the worker's cross-tenant discovery filters on
-- `status` and no index led with it — client mail grows the table.
--
-- Lock cost: re-adding `email_messages_template_check` scans email_messages
-- under ACCESS EXCLUSIVE, as 0103 did; the new CHECKs on clients and
-- client_contacts scan those small tables. Accepted at deploy: every
-- existing row satisfies each one by construction (NULL / the defaults).
ALTER TABLE "client_contacts" ADD COLUMN "email_events" text[] DEFAULT '{}'::text[] NOT NULL;--> statement-breakpoint
ALTER TABLE "clients" ADD COLUMN "email_reply_to" text;--> statement-breakpoint
ALTER TABLE "email_messages" ADD COLUMN "client_id" uuid;--> statement-breakpoint
ALTER TABLE "email_messages" ADD COLUMN "dedupe_key" text;--> statement-breakpoint
ALTER TABLE "email_messages" ADD COLUMN "priority" smallint DEFAULT 0 NOT NULL;--> statement-breakpoint
-- ── hand-amended: the size guard (A12) — before any build below ──────────
DO $$
BEGIN
	IF (SELECT count(*) FROM (SELECT 1 FROM "email_messages" LIMIT 200001) s) > 200000
	   AND (SELECT count(*) FROM pg_class WHERE relkind = 'i' AND relname IN (
		'email_messages_dedupe_unique', 'email_messages_client_created_idx', 'email_messages_client_address_idx',
		'email_messages_claim_idx', 'email_messages_pending_next_idx', 'email_messages_pending_created_idx',
		'email_messages_updated_idx'
	   )) < 7 THEN
		RAISE EXCEPTION 'migration 0114: email_messages holds more than 200,000 rows — pre-build its seven new access paths CONCURRENTLY under the same names first (DEPLOY.md §5), then re-run.';
	END IF;
END $$;--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "email_messages_dedupe_unique" ON "email_messages" USING btree ("tenant_id","dedupe_key") WHERE dedupe_key IS NOT NULL;--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "email_messages_client_created_idx" ON "email_messages" USING btree ("tenant_id","client_id","created_at" DESC NULLS LAST,"id" DESC NULLS LAST) WHERE client_id IS NOT NULL;--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "email_messages_client_address_idx" ON "email_messages" USING btree ("tenant_id","client_id","to_email","created_at" DESC NULLS LAST,"id" DESC NULLS LAST) WHERE client_id IS NOT NULL;--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "email_messages_claim_idx" ON "email_messages" USING btree ("tenant_id","status","priority","next_attempt_at");--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "email_messages_pending_next_idx" ON "email_messages" USING btree ("next_attempt_at") WHERE status = 'pending';--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "email_messages_pending_created_idx" ON "email_messages" USING btree ("created_at") WHERE status = 'pending';--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "email_messages_updated_idx" ON "email_messages" USING btree ("status","updated_at");--> statement-breakpoint
-- ── hand-amended: a contact's email events ────────────────────────────────
-- A subset of the vocabulary with no NULL and no duplicate (the 0077
-- `client_contacts_roles_check` shape). Pinned against `CLIENT_EMAIL_EVENTS`
-- (modules/clients/clients.schema.ts) by test/client-master.spec.ts.
ALTER TABLE "client_contacts" ADD CONSTRAINT "client_contacts_email_events_check" CHECK (
	"email_events" <@ ARRAY['receipt.recorded', 'order.dispatched']::text[]
	AND array_position("email_events", NULL) IS NULL
	AND coalesce(cardinality(array_positions("email_events", 'receipt.recorded')), 0) <= 1
	AND coalesce(cardinality(array_positions("email_events", 'order.dispatched')), 0) <= 1
);--> statement-breakpoint
-- ── hand-amended: the client's Reply-To (the contact email shape, 0077) ──
ALTER TABLE "clients" ADD CONSTRAINT "clients_email_reply_to_format" CHECK (
	"email_reply_to" IS NULL OR (
		"email_reply_to" = lower(btrim("email_reply_to"))
		AND char_length("email_reply_to") BETWEEN 3 AND 254
		AND strpos("email_reply_to", '@') > 1
	)
);--> statement-breakpoint
-- ── hand-amended: the mail templates gain the two client mails (D3) ───────
-- §4: the old vocabulary must survive the widening — asserted, not reviewed.
DO $$
BEGIN
	IF EXISTS (
		SELECT 1 FROM unnest(ARRAY['user-invite', 'password-reset', 'password-changed']) AS old(template)
		WHERE old.template <> ALL (ARRAY['user-invite', 'password-reset', 'password-changed', 'client-receipt', 'client-dispatch'])
	) THEN
		RAISE EXCEPTION 'migration 0114: the widened template vocabulary lost an account template.';
	END IF;
END $$;--> statement-breakpoint
-- Pinned against `EMAIL_TEMPLATES` (modules/mail/mail-rules.ts) by test/mail.spec.ts.
ALTER TABLE "email_messages" DROP CONSTRAINT "email_messages_template_check";--> statement-breakpoint
ALTER TABLE "email_messages" ADD CONSTRAINT "email_messages_template_check" CHECK ("template" IN ('user-invite', 'password-reset', 'password-changed', 'client-receipt', 'client-dispatch'));--> statement-breakpoint
-- A client mail names its client and its dedupe key; account mail neither.
ALTER TABLE "email_messages" ADD CONSTRAINT "email_messages_client_shape_check" CHECK (
	("template" IN ('client-receipt', 'client-dispatch') AND "client_id" IS NOT NULL AND "dedupe_key" IS NOT NULL)
	OR ("template" NOT IN ('client-receipt', 'client-dispatch') AND "client_id" IS NULL AND "dedupe_key" IS NULL)
);--> statement-breakpoint
ALTER TABLE "email_messages" ADD CONSTRAINT "email_messages_dedupe_key_format" CHECK (
	"dedupe_key" IS NULL OR char_length("dedupe_key") BETWEEN 1 AND 400
);--> statement-breakpoint
-- 0 = account mail (claimed first), 1 = client mail (`EMAIL_TEMPLATE_PRIORITY`).
ALTER TABLE "email_messages" ADD CONSTRAINT "email_messages_priority_check" CHECK ("priority" IN (0, 1));--> statement-breakpoint
-- ── the post-migration assertion (the 0064/0089/0103 model) ───────────────
-- Made-up uuids. The accepted shapes are inserted first and rolled back by a
-- sentinel exception, so a CHECK that refused everything fails the
-- migration; each refused shape runs in its own subtransaction and must be
-- refused BY ITS NAMED CONSTRAINT (each violates only its target — CHECKs run
-- in name order, so a probe that broke an earlier-named one would name it).
DO $$
DECLARE
	t uuid := gen_random_uuid();
	c uuid := gen_random_uuid();
	u uuid := gen_random_uuid();
	refused_by text;
	expected text;
	probe text;
BEGIN
	-- (1) accepted shapes: both client templates with a client and a key
	-- (priority 1); an invite with neither (priority 0); each email-events
	-- subset; a null and a valid Reply-To.
	BEGIN
		INSERT INTO "email_messages" ("id","tenant_id","template","to_email","params","status","next_attempt_at","client_id","dedupe_key","priority")
		VALUES (gen_random_uuid(), t, 'client-receipt', 'a@example.in', '{}', 'pending', now(), c, 'client-receipt:g:a@example.in', 1),
		       (gen_random_uuid(), t, 'client-dispatch', 'a@example.in', '{}', 'pending', now(), c, 'client-dispatch:o:a@example.in', 1),
		       (gen_random_uuid(), t, 'user-invite', 'a@example.in', '{}', 'pending', now(), NULL, NULL, 0);
		INSERT INTO "client_contacts" ("id","tenant_id","client_id","name","email","email_events")
		VALUES (gen_random_uuid(), t, c, 'Probe one', 'p1@example.in', '{}'),
		       (gen_random_uuid(), t, c, 'Probe two', 'p2@example.in', ARRAY['receipt.recorded']),
		       (gen_random_uuid(), t, c, 'Probe three', 'p3@example.in', ARRAY['order.dispatched']),
		       (gen_random_uuid(), t, c, 'Probe four', 'p4@example.in', ARRAY['receipt.recorded', 'order.dispatched']);
		INSERT INTO "clients" ("id","tenant_id","code","name","email_reply_to")
		VALUES (gen_random_uuid(), t, 'PROBE-0114-A', 'Probe A', NULL),
		       (gen_random_uuid(), t, 'PROBE-0114-B', 'Probe B', 'ops@3pl.example.in');
		RAISE EXCEPTION USING ERRCODE = 'P0114', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation OR unique_violation THEN
			RAISE EXCEPTION 'migration 0114: an accepted shape was refused (%).', SQLERRM;
		WHEN SQLSTATE 'P0114' THEN
			NULL; -- the accepted shapes landed, and the sentinel rolled them back
	END;
	-- (2) refused shapes, each by its named constraint.
	FOREACH probe IN ARRAY ARRAY[
		'client template without a client',
		'invite with a dedupe key',
		'invite with a client and no key',
		'unknown template',
		'priority 2',
		'empty dedupe key',
		'unknown email event',
		'null email event',
		'duplicate email event',
		'upper-case reply-to',
		'duplicate dedupe key'
	] LOOP
		refused_by := NULL;
		expected := CASE probe
			WHEN 'unknown template' THEN 'email_messages_template_check'
			WHEN 'priority 2' THEN 'email_messages_priority_check'
			WHEN 'empty dedupe key' THEN 'email_messages_dedupe_key_format'
			WHEN 'unknown email event' THEN 'client_contacts_email_events_check'
			WHEN 'null email event' THEN 'client_contacts_email_events_check'
			WHEN 'duplicate email event' THEN 'client_contacts_email_events_check'
			WHEN 'upper-case reply-to' THEN 'clients_email_reply_to_format'
			WHEN 'duplicate dedupe key' THEN 'email_messages_dedupe_unique'
			ELSE 'email_messages_client_shape_check'
		END;
		BEGIN
			CASE probe
				WHEN 'client template without a client' THEN
					INSERT INTO "email_messages" ("id","tenant_id","template","to_email","params","status","next_attempt_at","client_id","dedupe_key","priority")
					VALUES (gen_random_uuid(), t, 'client-receipt', 'a@example.in', '{}', 'pending', now(), NULL, 'k', 1);
				WHEN 'invite with a dedupe key' THEN
					INSERT INTO "email_messages" ("id","tenant_id","template","to_email","params","status","next_attempt_at","client_id","dedupe_key","priority")
					VALUES (gen_random_uuid(), t, 'user-invite', 'a@example.in', '{}', 'pending', now(), NULL, 'k', 0);
				WHEN 'invite with a client and no key' THEN
					INSERT INTO "email_messages" ("id","tenant_id","template","to_email","params","status","next_attempt_at","client_id","dedupe_key","priority")
					VALUES (gen_random_uuid(), t, 'user-invite', 'a@example.in', '{}', 'pending', now(), c, NULL, 0);
				WHEN 'unknown template' THEN
					INSERT INTO "email_messages" ("id","tenant_id","template","to_email","params","status","next_attempt_at","client_id","dedupe_key","priority")
					VALUES (gen_random_uuid(), t, 'client-invoice', 'a@example.in', '{}', 'pending', now(), NULL, NULL, 0);
				WHEN 'priority 2' THEN
					INSERT INTO "email_messages" ("id","tenant_id","template","to_email","params","status","next_attempt_at","client_id","dedupe_key","priority")
					VALUES (gen_random_uuid(), t, 'user-invite', 'a@example.in', '{}', 'pending', now(), NULL, NULL, 2);
				WHEN 'empty dedupe key' THEN
					INSERT INTO "email_messages" ("id","tenant_id","template","to_email","params","status","next_attempt_at","client_id","dedupe_key","priority")
					VALUES (gen_random_uuid(), t, 'client-dispatch', 'a@example.in', '{}', 'pending', now(), c, '', 1);
				WHEN 'unknown email event' THEN
					INSERT INTO "client_contacts" ("id","tenant_id","client_id","name","email","email_events")
					VALUES (gen_random_uuid(), t, c, 'Probe', 'px@example.in', ARRAY['invoice.issued']);
				WHEN 'null email event' THEN
					INSERT INTO "client_contacts" ("id","tenant_id","client_id","name","email","email_events")
					VALUES (gen_random_uuid(), t, c, 'Probe', 'px@example.in', ARRAY[NULL]::text[]);
				WHEN 'duplicate email event' THEN
					INSERT INTO "client_contacts" ("id","tenant_id","client_id","name","email","email_events")
					VALUES (gen_random_uuid(), t, c, 'Probe', 'px@example.in', ARRAY['order.dispatched', 'order.dispatched']);
				WHEN 'upper-case reply-to' THEN
					INSERT INTO "clients" ("id","tenant_id","code","name","email_reply_to")
					VALUES (gen_random_uuid(), t, 'PROBE-0114-C', 'Probe C', 'Ops@3pl.example.in');
				WHEN 'duplicate dedupe key' THEN
					INSERT INTO "email_messages" ("id","tenant_id","template","to_email","params","status","next_attempt_at","client_id","dedupe_key","priority")
					VALUES (gen_random_uuid(), t, 'client-receipt', 'a@example.in', '{}', 'pending', now(), c, 'client-receipt:dup:a@example.in', 1),
					       (gen_random_uuid(), t, 'client-receipt', 'a@example.in', '{}', 'pending', now(), c, 'client-receipt:dup:a@example.in', 1);
			END CASE;
			RAISE EXCEPTION USING ERRCODE = 'P0114', MESSAGE = 'a refused probe landed';
		EXCEPTION
			WHEN check_violation OR unique_violation THEN
				GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
			WHEN SQLSTATE 'P0114' THEN
				refused_by := NULL;
		END;
		IF refused_by IS DISTINCT FROM expected THEN
			RAISE EXCEPTION 'migration 0114: probe "%" was refused by % (expected %).', probe, coalesce(refused_by, 'nothing'), expected;
		END IF;
	END LOOP;
	IF EXISTS (SELECT 1 FROM "email_messages" WHERE "tenant_id" = t)
	   OR EXISTS (SELECT 1 FROM "client_contacts" WHERE "tenant_id" = t)
	   OR EXISTS (SELECT 1 FROM "clients" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0114: a probe row survived.';
	END IF;
END $$;
